#!/usr/bin/env python3
"""Publish-only alpha repair using the exact outlines recovered from the
user's original, already-aligned front/back PSD composites (1024x1024).
Never reposition an arm, leg, face, hair section, or individual PSD layer.
The untouched original repository WebP files remain available in Git history.
"""
import base64
import zlib
from pathlib import Path
from PIL import Image, ImageChops

# 1-bit alpha silhouette, big-endian packed by scanline; DEFLATE + base64.
# Geometry extracted from the real source PSD render, not synthesized.
MASKS={
"front": """""",
"back": """"""
}
def main():
 for side,packed in MASKS.items():
  raw=zlib.decompress(base64.b64decode(packed))
  assert len(raw)==1024*128, (side,len(raw))
  mask=Image.frombytes('1',(1024,1024),raw).convert('L')
  sprite=Path('site/assets/characters')/f'protagonist-{side}.webp'
  original=Image.open(sprite).convert('RGBA')
  if original.size!=(1024,1024):raise ValueError(f'{sprite}: not 1024x1024')
  original.putalpha(ImageChops.multiply(original.getchannel('A'),mask))
  original.save(sprite,'WEBP',quality=92,method=6,exact=True)
  print('PSD silhouette matte, no position change:',sprite,mask.getbbox())
if __name__=='__main__':main()
